import{_ as t,a0 as l,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何修復 WordPress 中的 HTTP 錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"如何修復 WordPress 中的 HTTP 錯誤 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修復 WordPress 中的 HTTP 錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修復 WordPress 中的 HTTP 錯誤 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180102 HTTP errors in WordPress","title":"如何修復 WordPress 中的 HTTP 錯誤","tag":"201803","desc":""},"relativePath":"201803/20180102 HTTP errors in WordPress.md","filePath":"[post].md"}'),c={name:"201803/20180102 HTTP errors in WordPress.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何修復-wordpress-中的-http-錯誤" tabindex="-1">如何修復 WordPress 中的 HTTP 錯誤 <a class="header-anchor" href="#如何修復-wordpress-中的-http-錯誤" aria-label="Permalink to “如何修復 WordPress 中的 HTTP 錯誤”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2018/01/http-error-wordpress.jpg" alt="http error wordpress"></p><p>我們會向你介紹，如何在 Linux VPS 上修復 WordPress 中的 HTTP 錯誤。 下面列出了 WordPress 用户遇到的最常見的 HTTP 錯誤，我們的建議側重於如何發現錯誤原因以及解決方法。</p><h3 id="_1、-修復在上傳圖像時出現的-http-錯誤" tabindex="-1">1、 修復在上傳圖像時出現的 HTTP 錯誤 <a class="header-anchor" href="#_1、-修復在上傳圖像時出現的-http-錯誤" aria-label="Permalink to “1、 修復在上傳圖像時出現的 HTTP 錯誤”">​</a></h3><p>如果你在基於 WordPress 的網頁中上傳圖像時出現錯誤，這也許是因為服務器上 PHP 的配置，例如存儲空間不足或者其他配置問題造成的。</p><p>用如下命令查找 php 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php -i | grep php.ini</span></span>
<span class="line"><span>Configuration File (php.ini) Path =&gt; /etc</span></span>
<span class="line"><span>Loaded Configuration File =&gt; /etc/php.ini</span></span></code></pre></div><p>根據輸出結果，php 配置文件位於 <code>/etc</code> 文件夾下。編輯 <code>/etc/php.ini</code> 文件，找出下列行，並按照下面的例子修改其中相對應的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/php.ini</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>upload_max_filesize = 64M</span></span>
<span class="line"><span>post_max_size = 32M</span></span>
<span class="line"><span>max_execution_time = 300</span></span>
<span class="line"><span>max_input_time 300</span></span>
<span class="line"><span>memory_limit = 128M</span></span></code></pre></div><p>當然，如果你不習慣使用 vi 文本編輯器，你可以選用自己喜歡的。</p><p>不要忘記重啓你的網頁服務器來讓改動生效。</p><p>如果你安裝的網頁服務器是 Apache，你也可以使用 <code>.htaccess</code> 文件。首先，找到 <code>.htaccess</code> 文件。它位於 WordPress 安裝路徑的根文件夾下。如果沒有找到 <code>.htaccess</code> 文件，需要自己手動創建一個，然後加入如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /www/html/path_to_wordpress/.htaccess</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php_value upload_max_filesize 64M</span></span>
<span class="line"><span>php_value post_max_size 32M</span></span>
<span class="line"><span>php_value max_execution_time 180</span></span>
<span class="line"><span>php_value max_input_time 180</span></span>
<span class="line"><span></span></span>
<span class="line"><span># BEGIN WordPress</span></span>
<span class="line"><span>&lt;IfModule mod_rewrite.c&gt;</span></span>
<span class="line"><span>  RewriteEngine On</span></span>
<span class="line"><span>  RewriteBase /</span></span>
<span class="line"><span>  RewriteRule ^index\\.php$ - [L]</span></span>
<span class="line"><span>  RewriteCond %{REQUEST_FILENAME} !-f</span></span>
<span class="line"><span>  RewriteCond %{REQUEST_FILENAME} !-d</span></span>
<span class="line"><span>  RewriteRule . /index.php [L]</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span>
<span class="line"><span># END WordPress</span></span></code></pre></div><p>如果你使用的網頁服務器是 nginx，在 nginx 的 <code>server</code> 配置塊中配置你的 WordPress 實例。詳細配置和下面的例子相似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  listen 80;</span></span>
<span class="line"><span>  client_max_body_size 128m;</span></span>
<span class="line"><span>  client_body_timeout 300;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  server_name your-domain.com www.your-domain.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  root /var/www/html/wordpress;</span></span>
<span class="line"><span>  index index.php;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location = /favicon.ico {</span></span>
<span class="line"><span>  log_not_found off;</span></span>
<span class="line"><span>  access_log off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location = /robots.txt {</span></span>
<span class="line"><span>    allow all;</span></span>
<span class="line"><span>    log_not_found off;</span></span>
<span class="line"><span>    access_log off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location / {</span></span>
<span class="line"><span>    try_files $uri $uri/ /index.php?$args;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location ~ \\.php$ {</span></span>
<span class="line"><span>    include fastcgi_params;</span></span>
<span class="line"><span>    fastcgi_pass 127.0.0.1:9000;</span></span>
<span class="line"><span>    fastcgi_index index.php;</span></span>
<span class="line"><span>    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  location ~* \\.(js|css|png|jpg|jpeg|gif|ico)$ {</span></span>
<span class="line"><span>    expires max;</span></span>
<span class="line"><span>    log_not_found off;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>根據自己的 PHP 配置，你需要將 <code>fastcgi_pass 127.0.0.1:9000;</code> 用類似於 <code>fastcgi_pass unix:/var/run/php7-fpm.sock;</code> 替換掉（依照實際連接方式）</p><p>重啓 nginx 服務來使改動生效。</p><h3 id="_2、-修復因為不恰當的文件權限而產生的-http-錯誤" tabindex="-1">2、 修復因為不恰當的文件權限而產生的 HTTP 錯誤 <a class="header-anchor" href="#_2、-修復因為不恰當的文件權限而產生的-http-錯誤" aria-label="Permalink to “2、 修復因為不恰當的文件權限而產生的 HTTP 錯誤”">​</a></h3><p>如果你在 WordPress 中出現一個意外錯誤，也許是因為不恰當的文件權限導致的，所以需要給 WordPress 文件和文件夾設置一個正確的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chown www-data:www-data -R /var/www/html/path_to_wordpress/</span></span></code></pre></div><p>將 <code>www-data</code> 替換成實際的網頁服務器用户，將 <code>/var/www/html/path_to_wordpress</code> 換成 WordPress 的實際安裝路徑。</p><h3 id="_3、-修復因為內存不足而產生的-http-錯誤" tabindex="-1">3、 修復因為內存不足而產生的 HTTP 錯誤 <a class="header-anchor" href="#_3、-修復因為內存不足而產生的-http-錯誤" aria-label="Permalink to “3、 修復因為內存不足而產生的 HTTP 錯誤”">​</a></h3><p>你可以通過在 <code>wp-config.php</code> 中添加如下內容來設置 PHP 的最大內存限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>define(&#39;WP_MEMORY_LIMIT&#39;, &#39;128MB&#39;);</span></span></code></pre></div><h3 id="_4、-修復因為-php-ini-文件錯誤配置而產生的-http-錯誤" tabindex="-1">4、 修復因為 php.ini 文件錯誤配置而產生的 HTTP 錯誤 <a class="header-anchor" href="#_4、-修復因為-php-ini-文件錯誤配置而產生的-http-錯誤" aria-label="Permalink to “4、 修復因為 php.ini 文件錯誤配置而產生的 HTTP 錯誤”">​</a></h3><p>編輯 PHP 配置主文件，然後找到 <code>cgi.fix_pathinfo</code> 這一行。 這一行內容默認情況下是被註釋掉的，默認值為 <code>1</code>。取消這一行的註釋（刪掉這一行最前面的分號），然後將 <code>1</code> 改為 <code>0</code> 。同時需要修改 <code>date.timezone</code> 這一 PHP 設置，再次編輯 PHP 配置文件並將這一選項改成 <code>date.timezone = Asia/Shanghai</code> （或者將等號後內容改為你所在的時區）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/php.ini</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cgi.fix_pathinfo=0</span></span>
<span class="line"><span>date.timezone = Asia/Shanghai</span></span></code></pre></div><h3 id="_5、-修復因為-apache-mod-security-模組而產生的-http-錯誤" tabindex="-1">5、 修復因為 Apache mod_security 模組而產生的 HTTP 錯誤 <a class="header-anchor" href="#_5、-修復因為-apache-mod-security-模組而產生的-http-錯誤" aria-label="Permalink to “5、 修復因為 Apache mod_security 模組而產生的 HTTP 錯誤”">​</a></h3><p>如果你在使用 Apache mod_security 模組，這可能也會引起問題。試着禁用這一模組，確認是否因為在 <code>.htaccess</code> 文件中加入如下內容而引起了問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_security.c&gt;</span></span>
<span class="line"><span>  SecFilterEngine Off</span></span>
<span class="line"><span>  SecFilterScanPOST Off</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><h3 id="_6、-修復因為有問題的插件-主題而產生的-http-錯誤" tabindex="-1">6、 修復因為有問題的插件/主題而產生的 HTTP 錯誤 <a class="header-anchor" href="#_6、-修復因為有問題的插件-主題而產生的-http-錯誤" aria-label="Permalink to “6、 修復因為有問題的插件/主題而產生的 HTTP 錯誤”">​</a></h3><p>一些插件或主題也會導致 HTTP 錯誤以及其他問題。你可以首先禁用有問題的插件/主題，或暫時禁用所有 WordPress 插件。如果你有 phpMyAdmin，使用它來禁用所有插件：在其中找到 <code>wp_options</code> 數據表，在 <code>option_name</code> 這一列中找到 <code>active_plugins</code> 這一記錄，然後將 <code>option_value</code> 改為 ：<code>a:0:{}</code>。</p><p>或者用以下命令通過SSH重命名插件所在文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv /www/html/path_to_wordpress/wp-content/plugins /www/html/path_to_wordpress/wp-content/plugins.old</span></span></code></pre></div><p>通常情況下，HTTP 錯誤會被記錄在網頁服務器的日誌文件中，所以尋找錯誤時一個很好的切入點就是查看服務器日誌。</p><hr>`,39)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.rosehosting.com/blog/http-error-wordpress/"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.rosehosting.com/blog/http-error-wordpress/",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://www.rosehosting.com"},{default:p(()=>[...s[2]||(s[2]=[a("rosehosting",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wenwensnow"},{default:p(()=>[...s[3]||(s[3]=[a("wenwensnow",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const w=t(c,[["render",h]]);export{T as __pageData,w as default};
